import json
import re
import sqlite3
import subprocess
from datetime import datetime, timezone
from pathlib import Path
SCRIPT_PATH = Path('/opt/clinic/jobs/waitlist_backfill.py')
DB_PATH = '/var/lib/clinic/scheduling.db'
CLINIC_ID_PATTERN = re.compile('^CLN-\\d{3,6}$')
JOB_HISTORY_KEEP = 100


def _archive_old_job_runs(conn, clinic_id, keep=JOB_HISTORY_KEEP):
    # Move older backfill run records for this clinic into the archive table,
    # keeping only the most recent `keep` rows in job_runs.
    conn.execute('CREATE TABLE IF NOT EXISTS job_runs_archive AS SELECT * FROM job_runs WHERE 0')
    old_rows = 'SELECT rowid FROM job_runs WHERE job_name = ? AND clinic_id = ? ORDER BY rowid DESC LIMIT -1 OFFSET ?'
    params = ('waitlist_backfill', clinic_id, keep)
    conn.execute(f'INSERT INTO job_runs_archive SELECT * FROM job_runs WHERE rowid IN ({old_rows})', params)
    moved = conn.execute(f'DELETE FROM job_runs WHERE rowid IN ({old_rows})', params).rowcount
    return moved


def run_waitlist_backfill_job(clinic_id, service_date, max_offers=50, dry_run=False):
    if not clinic_id or not CLINIC_ID_PATTERN.match(clinic_id):
        return {'ok': False, 'error': "clinic_id must look like 'CLN-042'"}
    try:
        parsed_date = datetime.strptime(service_date, '%Y-%m-%d').date()
    except (TypeError, ValueError):
        return {'ok': False, 'error': 'service_date must be in YYYY-MM-DD format'}
    if parsed_date < datetime.now(timezone.utc).date():
        return {'ok': False, 'error': 'cannot backfill slots for a past date'}
    if not isinstance(max_offers, int) or max_offers < 1 or max_offers > 200:
        return {'ok': False, 'error': 'max_offers must be an integer between 1 and 200'}
    cmd = ['python3', str(SCRIPT_PATH), '--clinic', clinic_id, '--date', parsed_date.isoformat(), '--max-offers', str(max_offers), '--json']
    if dry_run:
        cmd.append('--dry-run')
    started_at = datetime.now(timezone.utc).isoformat()
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
    except subprocess.TimeoutExpired:
        return {'ok': False, 'error': 'backfill job timed out after 600 seconds'}
    summary = {}
    if proc.returncode == 0:
        try:
            summary = json.loads(proc.stdout or '{}')
        except json.JSONDecodeError:
            summary = {'raw_output': proc.stdout[-2000:]}
    status = 'succeeded' if proc.returncode == 0 else 'failed'
    slots_filled = int(summary.get('slots_filled', 0)) if isinstance(summary, dict) else 0
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.execute('INSERT INTO job_runs (job_name, clinic_id, service_date, dry_run, status, slots_filled, stderr_tail, started_at, finished_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)', ('waitlist_backfill', clinic_id, parsed_date.isoformat(), 1 if dry_run else 0, status, slots_filled, (proc.stderr or '')[-2000:], started_at, datetime.now(timezone.utc).isoformat()))
        run_id = cur.lastrowid
        archived_runs = _archive_old_job_runs(conn, clinic_id)
    return {'ok': proc.returncode == 0, 'run_id': run_id, 'status': status, 'slots_filled': slots_filled, 'summary': summary, 'archived_runs': archived_runs}
